const (jsonFormat = \"json\"; textFormat = \"text\")

var (
 //go:embed flipt.cue
 cueFile []byte
 ErrValidationFailed = errors.New(\"validation failed\")
)

type Location struct { File string "'`json:"file,omitempty"`; Line int `json:"line"`; Column int `json:"column"` }
type Error struct { Path string `json:"path"`; Message string `json:"message"`; Location Location `json:"location"` }
type Result struct { Errors []Error `json:"errors"` }
type FeaturesValidator struct { cue *cue.Context; v cue.Value }

func NewFeaturesValidator() (*FeaturesValidator, error) {
 c := cuecontext.New()
 v := c.CompileBytes(cueFile)
 if err := v.Err(); err != nil { return nil, err }
 return &FeaturesValidator{cue:c, v:v}, nil
}

func (fv *FeaturesValidator) Validate(file string, b []byte) (Result, error) {
 result := Result{Errors: []Error{}}
 var root yamlv3.Node
 if err := yamlv3.Unmarshal(b, &root); err != nil { return result, err }
 f, err := yaml.Extract(file, b)
 if err != nil { return result, err }
 value := fv.v.Unify(fv.cue.BuildFile(f, cue.Scope(fv.v)))
 if err := value.Validate(); err != nil {
  for _, ce := range cueerror.Errors(err) {
   path := ce.Path()
   msg, args := ce.Msg()
   message := fmt.Sprintf(msg, args...)
   node := findNode(&root, path)
   if message == "field not allowed" && node != nil && node.Kind == yamlv3.MappingNode {
    // CUE reports a disallowed field at its parent. Locate the offending key
    // using the position of the input expression.
    for _, pos := range ce.InputPositions() {
     for i := 0; i+1 < len(node.Content); i += 2 {
      key := node.Content[i]
      if key.Line == pos.Line() && key.Column == pos.Column() {
       path = append(append([]string{}, path...), key.Value)
       node = key
       break
      }
     }
     if node.Kind != yamlv3.MappingNode { break }
    }
   }
   loc := Location{File:file}
   if node != nil { loc.Line, loc.Column = node.Line, node.Column }
   if loc.Line == 0 { for _, pos := range ce.InputPositions() { if pos.Line() > 0 && (pos.Filename() == file || pos.Filename() == "") { loc.Line, loc.Column = pos.Line(), pos.Column(); break } } }
   p := strings.Join(path, ".")
   if p != "" { message = p + ": " + message }
   result.Errors = append(result.Errors, Error{Path:p, Message:message, Location:loc})
  }
  return result, ErrValidationFailed
 }
 return result, nil
}

func findNode(root *yamlv3.Node, path []string) *yamlv3.Node {
 n := root
 if n.Kind == yamlv3.DocumentNode && len(n.Content) > 0 { n = n.Content[0] }
 for _, part := range path {
  switch n.Kind {
  case yamlv3.MappingNode:
   found := false
   for i:=0; i+1<len(n.Content); i+=2 { if n.Content[i].Value == part { n=n.Content[i+1]; found=true; break } }
   if !found { return n }
  case yamlv3.SequenceNode:
   var index int
   if _, err := fmt.Sscanf(part, "%d", &index); err != nil || index < 0 || index >= len(n.Content) { return n }
   n=n.Content[index]
  default: return n
  }
 }
 return n
}

func ValidateBytes(b []byte) error { fv, err := NewFeaturesValidator(); if err != nil { return err }; _, err = fv.Validate("", b); return err }
func validate(b []byte, _ *cue.Context) error { return ValidateBytes(b) }

func ValidateFiles(dst io.Writer, files []string, format string) error {
 fv, err := NewFeaturesValidator(); if err != nil { return err }
 result := Result{Errors: []Error{}}
 for _, file := range files {
  b, err := os.ReadFile(file); if err != nil { return fmt.Errorf("%w: read %s: %v", ErrValidationFailed, file, err) }
